const staticData = $getWorkflowStaticData('global');
const runId = $json.runId;
const run = staticData.runs?.[runId];

let text = '';
let pdfBase64 = null;
let fetchError = null;

try {
  if ($json.kind === 'pdf') {
    const fetchNode = $node['Fetch Text (HTML/CSV/JSON)'];
    if (fetchNode) {
      const raw = fetchNode.json;
      // Try to get base64 from binary response
      if (raw?.body) {
        try {
          const buf = Buffer.from(raw.body, 'binary');
          pdfBase64 = buf.toString('base64');
          text = '[PDF - sent to Claude vision for extraction]';
        } catch(e) {
          // fallback: treat as text
          text = (typeof raw.body === 'string' ? raw.body : JSON.stringify(raw)).slice(0, 60000);
        }
      } else if (typeof raw === 'string') {
        text = raw.slice(0, 60000);
      } else {
        text = JSON.stringify(raw).slice(0, 60000);
      }
    }
  } else {
    const fetchNode = $node['Fetch Text (HTML/CSV/JSON)'];
    if (fetchNode) {
      const raw = fetchNode.json;
      text = (typeof raw === 'string' ? raw : (raw?.body || JSON.stringify(raw))).slice(0, 60000);
    } else {
      const raw = $input.first().json;
      text = (typeof raw === 'string' ? raw : (raw?.body || JSON.stringify(raw))).slice(0, 60000);
    }
  }
} catch(e) {
  fetchError = e.message;
}

// Clean HTML
if ($json.kind === 'html' && text) {
  text = text
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Harvest links from HTML
const harvested = [];
if ($json.kind === 'html' && text) {
  const hrefRe = /href\s*=\s*["']([^"']+)["']/gi;
  let m;
  while ((m = hrefRe.exec(text)) !== null) {
    const href = m[1];
    try {
      const abs = new URL(href, $json.url).toString();
      const lu = abs.toLowerCase();
      if (lu.endsWith('.pdf') || lu.endsWith('.csv') || lu.includes('licit') || lu.includes('contrat') || lu.includes('presup') || lu.includes('boletin') || lu.includes('ordenanza')) {
        harvested.push(abs);
      }
    } catch(e) {}
  }
}

if (run) {
  run.step = 'fetch';
  run.progress = Math.min(55, (run.progress || 18) + 1);
  run.logs.push({ t: new Date().toISOString(), m: `Fetched ${($json.kind||'').toUpperCase()} ${$json.url}${pdfBase64 ? ' (PDF base64 captured)' : ''}${fetchError ? ' (error)' : ''}` });
  run.docs = run.docs || [];
  run.docs.push({
    url: $json.url,
    kind: $json.kind,
    fetched_at: new Date().toISOString(),
    text_preview: (text || '').slice(0, 8000),
    has_text: (!!text && !fetchError) || !!pdfBase64,
    has_pdf_binary: !!pdfBase64,
    error: fetchError
  });
  run._harvested = run._harvested || [];
  for (const h of harvested) run._harvested.push(h);
  run._harvested = [...new Set(run._harvested)].slice(0, 60);
}

// Pass pdfBase64 downstream for Claude vision extraction
return [{ json: { ...$json, text, pdfBase64 } }];
